'use strict';
async function api(url,data){const res=await fetch(url,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json'}:undefined,body:data?JSON.stringify(data):undefined});const result=await res.json();if(!res.ok)throw Error(result.error||'请求失败');return result;}
let serviceStatus=null,bridgeEntries=[],aiReview=null,reviewPending=false;
async function refreshStatus(){try{serviceStatus=await api('/api/status');$('.demo-pill').textContent=serviceStatus.configured?'AI 已配置 · '+serviceStatus.model:'模型未配置';}catch{$('.demo-pill').textContent='后端未连接';}}
const backendRender=render;
render=function(){backendRender();
 if(state.stage===0){const panel=document.createElement('section');panel.className='panel bridge-panel';panel.innerHTML=`<div class="panel-head"><div><h3>从微信导入</h3><small>微信多选聊天记录 → 分享到微信流（WeChatBridge） → 在这里选择记录</small></div><button class="button small" id="refreshBridge">刷新微信记录</button></div><div class="panel-body"><p id="bridgeStatus" class="subtle">也可以导入微信分享生成的 ZIP 文件。图片、语音附件暂不分析。</p><div id="bridgeFiles"></div><label for="selfName">我在记录中的昵称（可选，用于排除自己）</label><input id="selfName" value="${esc(state.selfName||'我')}" placeholder="我"><p class="subtle">点击生成画像后，当前选定记录将发送至 DMXAPI，用于画像和预演。</p></div>`;$('#view').prepend(panel);$('#fileInput').accept='.txt,.md,.json,.zip';$('.upload-zone p').textContent='支持 TXT、MD、JSON、微信 ZIP · ZIP 最大 40 MB';const foot=document.querySelector('.panel-foot .subtle');if(foot)foot.textContent='记录保存在本地；生成画像时将选定内容发送到 DMXAPI。';drawBridge();}
 if(state.stage===1){document.querySelectorAll('.persona-summary .subtle').forEach(el=>{const p=currentPersona();el.textContent=p.role+' · '+(p.model?'AI 画像 / '+p.model:'旧版画像，建议重新生成');});}
 if(state.stage===2){const tag=document.querySelector('.chat-heading .tag');if(tag)tag.textContent='AI 模拟回应';document.querySelectorAll('.hint-box').forEach(el=>{if(el.textContent.includes('正式版本将隔离'))el.innerHTML='<strong>对方的知识范围</strong><br>模型只收到共享背景、对象画像和本分支对话。你的私下目标与保护底线用于雷达判研和复盘，不传给模拟对方。';});const aside=document.querySelector('.preflight-right');if(aside){const box=document.createElement('section');box.className='panel';box.innerHTML='<div class="panel-head"><h3>表达改写与复盘</h3><button class="button small" id="aiReviewDraft">分析草稿并改写</button></div><div class="panel-body" id="aiReviewResult"></div>';aside.append(box);}drawReview();}
 if(state.stage===3){const box=document.createElement('section');box.className='panel';box.innerHTML='<div class="panel-head"><h3>AI 分支复盘</h3><button class="button small" id="aiReviewBranches">比较这两条路径</button></div><div class="panel-body" id="aiReviewResult"></div>';$('#view').append(box);drawReview();}
 document.querySelectorAll('.compare-message small').forEach(el=>{el.textContent=el.textContent.replace('演示回复','模拟回复');});
};
function drawBridge(){if(!$('#bridgeFiles'))return;$('#bridgeFiles').innerHTML=bridgeEntries.map(f=>`<div class="person-mini"><div><strong>${esc(f.name)}</strong><p>${esc(f.createdAt||'')}</p></div><button class="button small" data-import-bridge="${esc(f.id)}">导入这份记录</button></div>`).join('');}
generatePersonas=async function(){if(busy)return;if(!state.material.trim())return notify('请先导入聊天记录');busy=true;const button=$('#generatePersonas');if(button){button.disabled=true;button.textContent='正在从记录生成画像…';}try{const result=await api('/api/personas',{material:state.material,materialVersion:state.materialVersion,selfName:state.selfName||'我'});state.personas=result.personas.map(p=>({...p,confirmed:clone(p)}));state.selected=state.personas[0].id;createBranch(state.personas[0].confirmed);state.stage=1;notify('对象画像已生成，确认对象后点击预演即可。');}catch(e){notify(e.message);}finally{busy=false;render();}};
sendMessage=async function(){if(busy)return;const branch=currentBranch(),text=state.draft.trim();if(!branch)return notify('请先导入聊天并生成画像');if(!text)return notify('请输入消息');if(text.length>5000)return notify('每条消息最多 5000 字');if(branch.messages.at(-1)?.role==='user')return notify('上一条仍待回复，请从该消息分叉重试');const message={id:uid('msg'),role:'user',text,createdAt:new Date().toISOString()};branch.messages.push(message);state.draft='';busy=true;render();scrollChat();try{const result=await api('/api/rehearse',{persona:branch.persona,context:{background:branch.context.background},messages:branch.messages});branch.messages.push({id:uid('msg'),role:'assistant',text:result.text,model:result.model,createdAt:new Date().toISOString(),mode:'ai'});}catch(e){branch.messages.pop();state.draft=text;notify(e.message+'，草稿已保留');}finally{busy=false;render();scrollChat();}};
async function acceptMaterial(result){state.material=result.material;state.materialName=result.name;state.materialVersion++;state.sample=false;state.context={background:'',goal:'',boundary:''};state.draft='';state.stage=0;render();notify(`已导入 ${result.count} 条记录。核对自己的昵称后，点击生成画像。`);}
importFile=async function(file){if(!file||busy)return;if(file.size>40*1024*1024)return notify('文件最大 40 MB');busy=true;try{const base64=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=reject;r.readAsDataURL(file);});await acceptMaterial(await api('/api/upload',{name:file.name,base64}));}catch(e){notify(e.message);}finally{busy=false;}};
function drawReview(){const el=$('#aiReviewResult');if(!el)return;if(!aiReview){el.innerHTML='<p class="subtle">五维风险请查看上方 Jev 雷达；这里由聊天模型提供表达改写与语境复盘。</p>';return;}if(aiReview.branchId!==state.activeBranch||aiReview.stage!==state.stage){el.innerHTML='<p class="subtle">当前路径尚未分析，请点击上方按钮。</p>';return;}el.innerHTML=`<p>${esc(aiReview.summary)}</p>${aiReview.findings.map(f=>`<p><strong>${esc(f.quote)}</strong><br>${esc(f.reason)}</p>`).join('')}<div class="hint-box"><strong>候选表达</strong><p>${esc(aiReview.rewrite)}</p></div><button class="button small" id="useAiRewrite">放入草稿，继续预演</button><p class="subtle">模型：${esc(aiReview.model)} · 分析原文：${esc(aiReview.original)}</p>`;}
async function runReview(compare=false){if(reviewPending||busy)return;const branch=compare?state.branches.find(b=>b.id===state.compareB):currentBranch();if(!branch)return;const draft=compare?latestUser(branch)?.text:state.draft;if(!draft?.trim())return notify('先输入草稿或完成一轮对话');reviewPending=true;const branchId=state.activeBranch,stage=state.stage,button=$(compare?'#aiReviewBranches':'#aiReviewDraft');if(button){button.disabled=true;button.textContent='正在分析…';}try{const branches=compare?[state.compareA,state.compareB].map(id=>{const b=state.branches.find(x=>x.id===id);return {name:b.name,persona:b.persona,context:b.context,messages:b.messages};}):[];aiReview={...await api('/api/review',{persona:branch.persona,context:branch.context,draft,branches}),original:draft,branchId,stage};drawReview();}catch(e){notify(e.message);}finally{reviewPending=false;if(button){button.disabled=false;button.textContent=compare?'比较这两条路径':'分析草稿并改写';}}}
document.addEventListener('input',e=>{if(e.target.id==='selfName')state.selfName=e.target.value;});
document.addEventListener('click',async e=>{const button=e.target.closest('button');if(!button)return;try{
 if(button.id==='refreshBridge'){button.disabled=true;const result=await api('/api/bridge');bridgeEntries=result.files;drawBridge();$('#bridgeStatus').textContent=result.files.length?`找到 ${result.files.length} 份记录，请选择导入。`:`暂无记录。请先在微信流接收分享，或把 ZIP 放入 ${result.dropFolder} 后刷新。`;button.disabled=false;}
 if(button.dataset.importBridge&&!busy){busy=true;try{await acceptMaterial(await api('/api/bridge/import',{id:button.dataset.importBridge}));}finally{busy=false;}}
 if(button.id==='aiReviewDraft')await runReview();if(button.id==='aiReviewBranches')await runReview(true);
 if(button.id==='useAiRewrite'&&aiReview&&!busy){if(state.stage===3){const branch=state.branches.find(b=>b.id===state.compareB),last=latestUser(branch);createBranch(branch.persona,branch.messages.slice(0,branch.messages.findIndex(m=>m.id===last.id)),branch.id,last.id,branch.context);}state.draft=aiReview.rewrite;state.stage=2;render();}
 if(button.id==='modelSettings'){button.disabled=true;const result=await api('/api/models');$('#modelSelect').innerHTML=result.models.map(m=>`<option ${m===serviceStatus?.model?'selected':''}>${esc(m)}</option>`).join('');$('#modelDialog').showModal();button.disabled=false;}
 if(button.id==='saveModel'){await api('/api/settings',{model:$('#modelSelect').value});$('#modelDialog').close();await refreshStatus();notify('模型已切换');}
 if(button.id==='closeModel')$('#modelDialog').close();
 }catch(error){button.disabled=false;notify(error.message);}});
const modelButton=document.createElement('button');modelButton.id='modelSettings';modelButton.className='button small';modelButton.textContent='选择模型';$('.top-actions').prepend(modelButton);
const dialog=document.createElement('dialog');dialog.id='modelDialog';dialog.innerHTML='<div class="dialog-head"><h2>选择语言模型</h2><button id="closeModel" class="button small">关闭</button></div><p>列表来自 DMXAPI 当前密钥。调用费用按所选模型由服务商计费。</p><select id="modelSelect" style="width:100%;margin:20px 0"></select><button id="saveModel" class="button primary">使用此模型</button>';document.body.append(dialog);
refreshStatus();render();
